"""Owned, checkpointed installation of the pinned 3x-ui distribution.

No API/DB editing of pre-existing panels and no remote install script execution.
"""
import base64
import hashlib
import hmac
import json
import os
from pathlib import Path, PurePosixPath
import platform
import secrets
import shutil
import socket
import stat
import subprocess
import sys
import tarfile
import time
import urllib.request



PANEL = Path('/usr/local/x-ui')
DATABASE = Path('/etc/x-ui')
UNIT = Path('/etc/systemd/system/x-ui.service')
BOOT_UNIT = Path('/etc/systemd/system/antirkn-x-ui-bootstrap.service')
KEY = Path('/etc/antirkn-runner/panel.key')
CLI = Path('/usr/bin/x-ui')
STEPS = 6


class PanelError(Exception):
    def __init__(self, code):
        self.code = code


def digest(path):
    value = hashlib.sha256()
    with path.open('rb') as stream:
        for data in iter(lambda: stream.read(1048576), b''):
            value.update(data)
    return value.hexdigest()


def safe_file(path, max_size=1048576):
    meta = path.lstat()
    if (meta.st_uid != 0 or meta.st_mode & 0o022 or not stat.S_ISREG(meta.st_mode)
            or meta.st_size > max_size):
        raise PanelError('panel_conflict')


def atomic_file(path, data, mode=0o600):
    # A unique, exclusively created name: the RPC process and the daemon may
    # write the same record at once, and a fixed name let them interleave.
    # The suffix stays, staging scans skip files ending with it.
    temp = path.with_name('.' + path.name + '.' + secrets.token_hex(8) + '.antirkn-tmp')
    # All parents are root-owned and never supplied by the RPC caller.
    fd = os.open(str(temp), os.O_WRONLY | os.O_CREAT | os.O_EXCL | os.O_NOFOLLOW, mode)
    try:
        with os.fdopen(fd, 'wb') as stream:
            stream.write(data)
            stream.flush()
            os.fchmod(stream.fileno(), mode)
            os.fsync(stream.fileno())
        os.replace(str(temp), str(path))
    except BaseException:
        try:
            os.unlink(str(temp))
        except OSError:
            pass
        raise
    sync_directory(path.parent)


def sync_directory(path):
    fd = os.open(str(path), os.O_RDONLY | os.O_DIRECTORY)
    try:
        os.fsync(fd)
    finally:
        os.close(fd)


def atomic_copy(source, path, mode=0o600, owner=None):
    """atomic_file for large files: streamed, never read whole into memory.
    owner=(uid, gid) restores the original ownership of a replaced file."""
    temp = path.with_name('.' + path.name + '.' + secrets.token_hex(8) + '.antirkn-tmp')
    fd = os.open(str(temp), os.O_WRONLY | os.O_CREAT | os.O_EXCL | os.O_NOFOLLOW, mode)
    try:
        with os.fdopen(fd, 'wb') as stream, open(str(source), 'rb') as origin:
            shutil.copyfileobj(origin, stream, 1048576)
            stream.flush()
            if owner is not None:
                os.fchown(stream.fileno(), owner[0], owner[1])
            os.fchmod(stream.fileno(), mode)
            os.fsync(stream.fileno())
        os.replace(str(temp), str(path))
    except BaseException:
        try:
            os.unlink(str(temp))
        except OSError:
            pass
        raise
    sync_directory(path.parent)


SAFE_ENV = {'PATH': '/usr/sbin:/usr/bin:/sbin:/bin', 'LANG': 'C.UTF-8'}


def run(argv, timeout=30, input_data=None, env=None, cwd=None, capture=True):
    """The one subprocess call of the panel/component/apt modules: no shell,
    always bounded, a fixed environment, stderr discarded (it may quote
    configuration or upstream text)."""
    from sysutil import run as sysutil_run
    return sysutil_run(argv, input=input_data, timeout=timeout, cwd=cwd, capture=capture,
                       stderr=False, env=dict(SAFE_ENV) if env is None else env)


def command(argv, timeout=30, input_data=None):
    result = run(argv, timeout, input_data, env={**SAFE_ENV,
        'XUI_DB_FOLDER': str(DATABASE), 'XUI_BIN_FOLDER': str(PANEL / 'bin'),
        'XUI_LOG_FOLDER': str(DATABASE / 'logs'), 'XUI_ENABLE_FAIL2BAN': 'false'})
    if result.returncode != 0:
        raise PanelError('panel_api_failed')
    return result.stdout


class DownloadError(Exception):
    """reason: 'failed', 'checksum' or 'cancelled'; callers map it to their code."""
    def __init__(self, reason):
        self.reason = reason


def fetch_pinned(url, target, size, sha256, cancelled=None, limit=900):
    """Fetch an HTTPS artifact of a pinned size and SHA-256 to target.

    A verified target is reused. cancelled() is polled about once a second;
    the daemon's heartbeat thread keeps the worker alive meanwhile."""
    if target.is_file() and digest(target) == sha256:
        return target
    if not url.startswith('https://'):
        raise DownloadError('failed')
    import http.client
    temp = target.with_name(target.name + '.download')
    client = urllib.request.build_opener(urllib.request.ProxyHandler({}))
    total, value = 0, hashlib.sha256()
    deadline = time.monotonic() + limit
    polled = None
    try:
        with client.open(url, timeout=30) as response, temp.open('wb') as output:
            if not response.geturl().startswith('https://'):
                raise DownloadError('failed')
            while True:
                now = time.monotonic()
                if cancelled is not None and (polled is None or now - polled >= 1):
                    polled = now
                    if cancelled():
                        raise DownloadError('cancelled')
                data = response.read(1048576)
                if not data:
                    break
                total += len(data)
                if total > size or now > deadline:
                    raise DownloadError('failed')
                value.update(data)
                output.write(data)
            output.flush()
            os.fsync(output.fileno())
    except (OSError, ValueError, http.client.HTTPException):
        temp.unlink(missing_ok=True)
        raise DownloadError('failed') from None
    except DownloadError:
        temp.unlink(missing_ok=True)
        raise
    if total != size or value.hexdigest() != sha256:
        temp.unlink(missing_ok=True)
        raise DownloadError('checksum')
    os.replace(str(temp), str(target))
    sync_directory(target.parent)
    return target


def systemctl(*args):
    return command(['/usr/bin/systemctl', *args])


def port_free(port):
    try:
        with socket.socket() as sock:
            sock.setsockopt(socket.SOL_SOCKET, socket.SO_REUSEADDR, 1)
            sock.bind(('127.0.0.1', port))
        return True
    except OSError:
        return False


def prerequisites():
    missing = []
    distro = dict(line.split('=', 1) for line in Path('/etc/os-release').read_text().splitlines() if '=' in line)
    if distro.get('ID', '').strip('"') != 'ubuntu' or platform.machine() != 'x86_64':
        missing.append('ubuntu_x64')
    if sys.version_info < (3, 8) or not Path('/run/systemd/system').is_dir():
        missing.append('python_systemd')
    for path in ('/usr/bin/nsenter', '/usr/bin/systemctl'):
        if not Path(path).is_file():
            missing.append('util_linux_systemd')
    if not Path('/etc/ssl/certs/ca-certificates.crt').is_file():
        missing.append('ca_certificates')
    if shutil.disk_usage('/usr/local').free < 600 * 1024 * 1024:
        missing.append('disk_space')
    return sorted(set(missing))


def panel_plan(port):
    if port == 0:
        for _ in range(128):
            candidate = 10000 + secrets.randbelow(55536)
            if port_free(candidate):
                port = candidate
                break
        else:
            raise PanelError('panel_port_busy')
    paths = [PANEL, DATABASE, UNIT, BOOT_UNIT,
        Path('/usr/bin/x-ui'), Path('/usr/local/bin/x-ui'),
        Path('/lib/systemd/system/x-ui.service'), Path('/usr/bin/xray'),
        Path('/usr/local/bin/xray'), Path('/etc/xray'), Path('/usr/local/etc/xray'),
        Path('/etc/systemd/system/xray.service'), Path('/lib/systemd/system/xray.service')]
    snapshot = {}
    for path in paths:
        try:
            st = path.lstat()
            snapshot[str(path)] = [st.st_mode, st.st_uid, st.st_ino, st.st_mtime_ns]
        except FileNotFoundError:
            snapshot[str(path)] = None
    # A normal, stopped Docker installation is also pre-existing software.
    docker = shutil.which('docker')
    containers = []
    if docker:
        try:
            raw = command([docker, 'ps', '-a', '--format', '{{.Image}} {{.Names}}'], timeout=15).decode()
            containers = sorted(line for line in raw.splitlines()
                if any(value in line.lower() for value in ('3x-ui', '3xui', 'x-ui', 'xray')))
        except (PanelError, subprocess.SubprocessError):
            containers = ['unknown']
    snapshot['containers'] = containers
    missing = prerequisites()
    available = port_free(port)
    snapshot.update(port=port, available=available, prerequisites=missing,
                    release=RELEASE['sha256'])
    state = 'missing'
    if any(snapshot[str(p)] for p in paths) or containers:
        state = 'existing'
    fingerprint = hashlib.sha256(json.dumps(snapshot, sort_keys=True).encode()).hexdigest()
    return dict(state=state, supported=not missing, prerequisites=missing,
        port=port, portAvailable=available, fingerprint=fingerprint,
        panelVersion=RELEASE['panelVersion'], xrayVersion=RELEASE['xrayVersion'],
        sha256=RELEASE['sha256'], url=RELEASE['url'], bytes=RELEASE['bytes'])


def access_for(job_id, port):
    # Only a random root key is stored; job/event records never contain passwords.
    safe_file(KEY, 32)
    key = KEY.read_bytes()
    if len(key) != 32:
        raise PanelError('panel_conflict')
    password = base64.urlsafe_b64encode(hmac.new(key,
        ('3x-ui/admin/' + job_id).encode(), hashlib.sha256).digest()).decode().rstrip('=')
    path_file = DATABASE / '.antirkn-webpath'
    base_path = '/'
    if path_file.exists():
        safe_file(path_file, 128)
        base_path = path_file.read_text()
        import re
        if not re.fullmatch(r'/[A-Za-z0-9_-]{24}/', base_path):
            raise PanelError('panel_conflict')
    versions = {k: RELEASE[k] for k in ('panelVersion', 'xrayVersion')}
    version_file = DATABASE / '.antirkn-versions'
    if version_file.exists():
        safe_file(version_file, 1024)
        recorded = json.loads(version_file.read_text())
        if recorded.get('id') != job_id:
            raise PanelError('panel_conflict')
        versions = {k: recorded[k] for k in versions}
    return dict(id=job_id, port=port, basePath=base_path, username='antirkn', password=password, **versions)



def relogin_needed(error):
    """A lost or rejected session needs a new login; a refused connection
    (the panel is still starting) does not."""
    from urllib.error import HTTPError
    code = getattr(error, 'code', None)
    return (isinstance(error, HTTPError) and code in (401, 403, 404)) or (
        isinstance(error, ValueError) and str(error) in ('panel_auth_failed', 'panel_login_limited'))


def install_cli():
    """Install the unmodified, pinned upstream menu without running install.sh."""
    if CLI.exists() or CLI.is_symlink():
        safe_file(CLI, 1024 * 1024)
        if not os.access(CLI, os.X_OK): raise PanelError('panel_conflict')
        return  # Preserve any administrator-installed menu.
    if not (PANEL / 'x-ui').is_file(): raise PanelError('panel_existing')
    bundled = PANEL / 'x-ui.sh'
    if bundled.is_file():
        safe_file(bundled, RELEASE['cli']['bytes'])
        raw = bundled.read_bytes()
    else:
        client = urllib.request.build_opener(urllib.request.ProxyHandler({}))
        try:
            with client.open(RELEASE['cli']['url'], timeout=30) as response:
                if not response.geturl().startswith('https://'): raise PanelError('panel_download_failed')
                raw = response.read(RELEASE['cli']['bytes'] + 1)
        except OSError as error:
            raise PanelError('panel_download_failed') from error
    if len(raw) != RELEASE['cli']['bytes'] or hashlib.sha256(raw).hexdigest() != RELEASE['cli']['sha256']:
        raise PanelError('panel_checksum_failed')
    import tempfile
    fd, temporary = tempfile.mkstemp(prefix='.antirkn-x-ui-', dir=str(CLI.parent))
    try:
        with os.fdopen(fd, 'wb') as stream:
            stream.write(raw); stream.flush(); os.fsync(stream.fileno())
        os.chmod(temporary, 0o755)
        os.link(temporary, str(CLI))  # Exclusive: never replace another writer.
        parent = os.open(str(CLI.parent), os.O_RDONLY | os.O_DIRECTORY)
        try: os.fsync(parent)
        finally: os.close(parent)
    finally:
        os.unlink(temporary)


def unit_source(private=False):
    return ('[Unit]\nDescription=AntiRKN managed 3x-ui\nAfter=network.target\n'
        '[Service]\nType=simple\nWorkingDirectory=/usr/local/x-ui\n'
        'ExecStart=/usr/local/x-ui/x-ui\nRestart=on-failure\nRestartSec=3\n'
        'UMask=0077\nEnvironment=XUI_DB_FOLDER=/etc/x-ui\n'
        'Environment=XUI_BIN_FOLDER=/usr/local/x-ui/bin\n'
        'Environment=XUI_LOG_FOLDER=/etc/x-ui/logs\n'
        'Environment=XUI_ENABLE_FAIL2BAN=false\n'
        'StandardOutput=null\nStandardError=null\n'
        + ('PrivateNetwork=yes\n' if private else '')
        + '[Install]\nWantedBy=multi-user.target\n').encode()


class PanelInstaller:
    release = RELEASE
    def __init__(self, store, request):
        self.store, self.request = store, request
        self.directory = store.directory / ('panel-' + request['id'])
        self.ownership = self.directory / 'ownership.json'

    def cancelled(self):
        return bool(self.store.db.execute('SELECT cancel FROM jobs WHERE id=?',
            (self.request['id'],)).fetchone()[0])

    def owns(self):
        if not self.ownership.is_file():
            return False
        safe_file(self.ownership)
        record = json.loads(self.ownership.read_text())
        return record == dict(id=self.request['id'], fingerprint=self.request['fingerprint'])

    def checkpoint(self, number, code):
        with self.store.db:
            self.store.db.execute('UPDATE jobs SET checkpoint=? WHERE id=?', (number, self.request['id']))
            self.store.event(self.request['id'], code, number, STEPS)

    def assert_owned(self):
        if not self.owns():
            raise PanelError('panel_conflict')
        # A fresh installation only: changes by an administrator block resume.
        for path in (PANEL, DATABASE):
            if path.exists():
                st = path.lstat()
                if not stat.S_ISDIR(st.st_mode) or st.st_uid != 0 or st.st_mode & 0o022:
                    raise PanelError('panel_conflict')
                marker = path / '.antirkn-owner'
                safe_file(marker, 32)
                if marker.read_text() != self.request['id']:
                    raise PanelError('panel_conflict')
        for path, private in ((UNIT, False), (BOOT_UNIT, True)):
            if path.exists() or path.is_symlink():
                safe_file(path)
                if path.read_bytes() != unit_source(private):
                    raise PanelError('panel_conflict')

    def download(self):
        release = self.release
        try:
            return fetch_pinned(release['url'], self.directory / 'release.tar.gz',
                                release['bytes'], release['sha256'], self.cancelled)
        except DownloadError as error:
            raise PanelError({'cancelled': 'cancelled', 'checksum': 'panel_checksum_failed'}.get(
                error.reason, 'panel_download_failed')) from None

    def unpack(self, archive):
        release = self.release
        if digest(archive) != release['sha256']:
            raise PanelError('panel_checksum_failed')
        target = self.directory / 'extracted'
        target.mkdir(mode=0o700, exist_ok=True)
        with tarfile.open(str(archive), 'r:gz') as bundle:
            seen, expanded = set(), 0
            for entry in bundle.getmembers():
                name = PurePosixPath(entry.name)
                if name.is_absolute() or '..' in name.parts or not (entry.isfile() or entry.isdir()):
                    raise PanelError('panel_checksum_failed')
                relative = str(name)[5:] if str(name).startswith('x-ui/') else ''
                if relative not in release['files']:
                    continue
                if relative in seen or entry.size > 200 * 1024 * 1024:
                    raise PanelError('panel_checksum_failed')
                seen.add(relative)
                expanded += entry.size
                if expanded > 500 * 1024 * 1024:
                    raise PanelError('panel_checksum_failed')
                path = target / relative
                path.parent.mkdir(mode=0o700, parents=True, exist_ok=True)
                with bundle.extractfile(entry) as src, path.open('wb') as dst:
                    shutil.copyfileobj(src, dst)
                    dst.flush(); os.fsync(dst.fileno())
                if digest(path) != release['files'][relative]:
                    raise PanelError('panel_checksum_failed')
                path.chmod(0o755 if relative in ('x-ui', 'x-ui.sh', 'bin/xray-linux-amd64') else 0o644)
            if seen != set(release['files']):
                raise PanelError('panel_checksum_failed')
        return target

    def extract(self, archive):
        target = self.unpack(archive)
        # Only after a complete verified extraction do we reserve the destinations.
        if not self.owns():
            current = panel_plan(self.request['port'])
            if current['fingerprint'] != self.request['fingerprint']:
                raise PanelError('panel_conflict')
            atomic_file(self.ownership, json.dumps(dict(id=self.request['id'],
                fingerprint=self.request['fingerprint'])).encode())
        self.assert_owned()
        if not PANEL.exists():
            # Atomic rename on the same filesystem: staging lives under /usr/local.
            staging = PANEL.with_name('.x-ui-antirkn-' + self.request['id'])
            if staging.exists():
                shutil.rmtree(str(staging))
            shutil.copytree(str(target), str(staging))
            atomic_file(staging / '.antirkn-owner', self.request['id'].encode())
            staging.chmod(0o755)
            (staging / 'bin').chmod(0o755)
            os.rename(str(staging), str(PANEL))
        if not (PANEL / 'x-ui.sh').exists():
            atomic_file(PANEL / 'x-ui.sh', (target / 'x-ui.sh').read_bytes(), 0o755)
        for name, expected in RELEASE['files'].items():
            path = PANEL / name
            safe_file(path, 200 * 1024 * 1024)
            if digest(path) != expected:
                raise PanelError('panel_conflict')
        if not DATABASE.exists():
            staging_db = DATABASE.with_name('.x-ui-antirkn-' + self.request['id'])
            staging_db.mkdir(mode=0o700, exist_ok=True)
            atomic_file(staging_db / '.antirkn-owner', self.request['id'].encode())
            os.rename(str(staging_db), str(DATABASE))
        if not KEY.exists():
            KEY.parent.mkdir(mode=0o700, exist_ok=True)
            meta = KEY.parent.lstat()
            if not stat.S_ISDIR(meta.st_mode) or meta.st_uid != 0 or meta.st_mode & 0o077:
                raise PanelError('panel_conflict')
            atomic_file(KEY, secrets.token_bytes(32))

    def configure(self):
        self.assert_owned()
        path_file = DATABASE / '.antirkn-webpath'
        if not path_file.exists():
            atomic_file(path_file, ('/' + secrets.token_urlsafe(18) + '/').encode())
        access = access_for(self.request['id'], self.request['port'])
        command([str(PANEL / 'x-ui'), 'setting', '-listenIP', '127.0.0.1',
                 '-port', str(self.request['port']), '-webBasePath', access['basePath']], timeout=90)
        atomic_file(BOOT_UNIT, unit_source(True), 0o644)
        systemctl('daemon-reload')
        systemctl('start', BOOT_UNIT.name)
        access = access_for(self.request['id'], self.request['port'])
        helper = Path(__file__).with_name('panel_api.py')
        deadline = time.monotonic() + 120
        while time.monotonic() < deadline:
            pid = systemctl('show', '-p', 'MainPID', '--value', BOOT_UNIT.name).decode().strip()
            if pid.isdecimal() and int(pid) > 1:
                try:
                    command(['/usr/bin/nsenter', '--target', pid, '--net',
                             '/usr/bin/python3', '-I', str(helper)], timeout=60,
                            input_data=json.dumps(access).encode())
                    break
                except (PanelError, subprocess.SubprocessError):
                    pass
            time.sleep(1)
        else:
            raise PanelError('panel_api_failed')
        systemctl('stop', BOOT_UNIT.name)

    def start(self):
        self.assert_owned()
        install_cli()
        if not UNIT.exists():
            if not port_free(self.request['port']):
                raise PanelError('panel_port_busy')
            atomic_file(UNIT, unit_source(False), 0o644)
        systemctl('daemon-reload')
        systemctl('enable', '--now', UNIT.name)

    def verify(self):
        from panel_api import PanelApi
        self.assert_owned()
        access = access_for(self.request['id'], self.request['port'])
        deadline = time.monotonic() + 90
        api = None
        while time.monotonic() < deadline:
            try:
                # One session for the whole wait: a login per second could
                # trip 3x-ui's login limiter.
                if api is None:
                    session = PanelApi(access['port'], access.get('basePath', '/'))
                    session.login(access['username'], access['password'])
                    api = session
                settings = api.call('/panel/api/setting/all', {})
                inbounds = api.call('/panel/api/inbounds/list')
                status = api.call('/panel/api/server/status')
                # Right after start 3x-ui answers success with an empty
                # status (obj null, xray null) until its collector runs: not
                # ready yet, retry. An AttributeError here used to crash the
                # runner daemon on every fresh panel install.
                xray = status.get('xray') if isinstance(status, dict) else None
                if not isinstance(settings, dict) or not isinstance(xray, dict):
                    raise ValueError('panel_api_failed')
                if (settings.get('webListen') != '127.0.0.1'
                        or settings.get('webPort') != access['port']
                        or settings.get('webBasePath') != access['basePath']
                        or settings.get('subEnable') is not False
                        or inbounds != []):
                    raise PanelError('panel_conflict')
                if (xray.get('state') != 'running'
                        or xray.get('version') != RELEASE['xrayVersion']
                        or status.get('panelVersion') != RELEASE['panelVersion']):
                    raise ValueError('panel_api_failed')
                if command([str(PANEL / 'x-ui'), '-v']).decode().strip() != RELEASE['panelVersion']:
                    raise PanelError('panel_conflict')
                version = command([str(PANEL / 'bin/xray-linux-amd64'), 'version']).decode()
                if not version.startswith('Xray ' + RELEASE['xrayVersion'] + ' '):
                    raise PanelError('panel_conflict')
                systemctl('is-active', '--quiet', UNIT.name)
                return
            except (OSError, ValueError, subprocess.SubprocessError) as error:
                if relogin_needed(error):
                    api = None
                time.sleep(1)
        raise PanelError('panel_api_failed')

    def step(self, checkpoint):
        if prerequisites():
            raise PanelError('panel_prerequisites')
        if checkpoint > 0:
            with self.store.db:
                self.store.event(self.request['id'], ['running', 'panel_downloading',
                    'panel_extracting', 'panel_configuring', 'panel_starting',
                    'panel_checking'][checkpoint], checkpoint, STEPS)
        if checkpoint == 0:
            current = panel_plan(self.request['port'])
            if not current['supported']:
                raise PanelError('panel_prerequisites')
            if current['state'] != 'missing':
                raise PanelError('panel_existing')
            if not current['portAvailable']:
                raise PanelError('panel_port_busy')
            if current['fingerprint'] != self.request['fingerprint']:
                raise PanelError('panel_conflict')
            self.directory.mkdir(mode=0o700, exist_ok=True)
        elif checkpoint == 1:
            self.download()
        elif checkpoint == 2:
            self.extract(self.directory / 'release.tar.gz')
        elif checkpoint == 3:
            self.configure()
        elif checkpoint == 4:
            self.start()
        elif checkpoint == 5:
            self.verify()
        self.checkpoint(checkpoint + 1, ['running', 'panel_download', 'panel_extract',
            'panel_configure', 'panel_start', 'panel_check'][checkpoint])

    def abort(self):
        # The durable result retains applied files. Never claim cancellation undid them.
        if self.owns():
            try:
                systemctl('stop', BOOT_UNIT.name)
            except (PanelError, OSError, subprocess.SubprocessError):
                pass
            return 'partially_applied'
        return 'cancelled'

RELEASES = {'trusttunnel': {'version': '1.1.0', 'repository': 'TrustTunnel/TrustTunnel', 'archives': {'endpoint': {'url': 'https://github.com/TrustTunnel/TrustTunnel/releases/download/v1.1.0/trusttunnel-v1.1.0-linux-x86_64.tar.gz', 'bytes': 10608905, 'sha256': '91c2ea3db7416a01b5258a4c047ec22890490bc55e1b194206031aa75144f0e7', 'files': {'trusttunnel_endpoint': '9bb15f4e30e2ff196cf0aa387462c42387d9405ddfeb5caad133838560fa33cd', 'trusttunnel_endpoint.sig': '2049ddc410c91868fa26cedfbbbf7430bdd84a686d698f0a2bd607e24d4b70ac', 'setup_wizard': '6ac3512a2cc0bffc15fcb90c69f49c9e1f8c82ea0d2855effd0b9408e2cbea91', 'setup_wizard.sig': '89b38eac2afde2b04f6dda76d031cacd5b871406b29c158c9c365217f9e8f745', 'LICENSE': 'cd994f29faba128fa963ccab364cdee0b51cdb399f98432c4bb6c7a6d017d3df', 'trusttunnel.service.template': 'ad1f4025c0817b2cd28112ac3e2d9318d4369b2d7bf19f4937b315c174cbdc61'}}}}, 'amneziawg': {'version': '3.1.20260828', 'toolsVersion': '3.1.20260812', 'repository': 'amnezia-vpn/amneziawg-go', 'commit': 'b5928efb6ca19f0153958460c3d141f04abc5c2e', 'archives': {'source': {'url': 'https://codeload.github.com/amnezia-vpn/amneziawg-go/tar.gz/b5928efb6ca19f0153958460c3d141f04abc5c2e', 'bytes': 132779, 'sha256': '10bf7458e090bf52f87df27adcd3904a60e4d17fab844d9415e46379147f1ab4'}, 'tools': {'url': 'https://github.com/amnezia-vpn/amneziawg-tools/releases/download/v3.1.20260812/ubuntu-22.04-amneziawg-tools.zip', 'bytes': 63115, 'sha256': '919e9d0a367c7c72f9c16b7d0a9e4840b943628353b2210a33cb4b582785ba56', 'files': {'awg-quick.sha256': '80c60c3aefafcdf236a1ee4f9e7ac529d2f869e499e341bb693bcd6b64528ddd', 'awg': '23d29323258166183eeeb288c1f9f08b879f3707e54591b1bfb2402413f6d8d8', 'awg-quick': 'f4bb0f5d63665ade87f0cb9f2185c43515cff09868637eb311f98f65a318722c', 'awg.sha256': 'b93ddcaccc9bf275d72d95d86db9e9fe0848e29060a18fdd0b5070f8a0298fe1'}}, 'go': {'url': 'https://go.dev/dl/go1.26.8.linux-amd64.tar.gz', 'bytes': 66897291, 'sha256': 'd0f743b33e8d8945e6b1f432edd15785c70507121d6e2a723b21285eddf8b57b'}}}}
"""Pinned server software lifecycle. Configuring endpoints/peers is separate.

One owned version directory and an atomic pointer; backups/checkpoints survive
SSH loss. Unknown installations and edits are never adopted automatically.
"""
import hashlib
import json
import os
from pathlib import Path, PurePosixPath
import platform
import re
import shutil
import signal
import stat
import subprocess
import tarfile
import time
import zipfile


from panel import (DownloadError, PanelError, atomic_copy, atomic_file, digest, fetch_pinned, run,
                   safe_file, sync_directory)
from sysutil import run as sysutil_run

BASE = Path('/usr/local/lib/antirkn-components')
BIN = Path('/usr/local/bin')
CONFIG = Path('/etc/antirkn-components')
UNITS = Path('/etc/systemd/system')
STEPS = 6
BUILD_PROCESSES = {}


class ComponentError(Exception):
    def __init__(self, code='component_conflict'):
        self.code = code


def encode(value):
    return json.dumps(value, sort_keys=True, separators=(',', ':')).encode()


def process_identity(pid):
    """[boot id, start time] of a live process, or None. A PID alone may name
    another process after a restart or a reboot."""
    try:
        boot = Path('/proc/sys/kernel/random/boot_id').read_text().strip()
        raw = Path('/proc/%d/stat' % pid).read_text()
        # Field 22 (starttime); the fields after the parenthesised name start at 3.
        return [boot, int(raw[raw.rindex(')') + 2:].split()[19])]
    except (OSError, ValueError, IndexError, TypeError):
        return None


def same_process(pid, identity):
    """Only a process proven to be the recorded one is ever signalled."""
    return (type(pid) is int and pid > 1 and isinstance(identity, list)
            and process_identity(pid) == identity)


def release_hash(component, release=None):
    return hashlib.sha256(encode(release or RELEASES[component])).hexdigest()


def usable(component, record):
    """Configuration code may use this AntiRKN install: the pinned version or
    a newer one of the same generation (installed by the checked update).
    Requiring exactly the pinned version made every update break AWG/TT edits.
    """
    if not record:
        return False
    pinned = RELEASES[component]
    try:
        for key in (('version', 'toolsVersion') if component == 'amneziawg' else ('version',)):
            have = tuple(int(x) for x in record[key].split('.'))
            want = tuple(int(x) for x in pinned[key].split('.'))
            if have[0] != want[0] or have < want:
                return False
    except (KeyError, TypeError, ValueError, AttributeError):
        return False
    return True


def release_for(component, payload=None):
    """The pinned release, or a newer upstream one the app chose (stable only).

    Only the version and its archive change; the source of the archive is
    fixed per component and its size and SHA-256 are checked on download.
    """
    base = RELEASES[component]
    if not payload:
        return base
    try:
        choice = json.loads(payload) if isinstance(payload, str) else payload
    except ValueError:
        raise ComponentError('component_incompatible')
    if not isinstance(choice, dict):
        raise ComponentError('component_incompatible')
    version, archive = choice.get('version'), choice.get('archive')
    if (not isinstance(version, str) or not re.fullmatch(r'[0-9]{1,4}\.[0-9]{1,4}\.[0-9]{1,10}', version)
            or not isinstance(archive, dict) or set(archive) != {'url', 'bytes', 'sha256'}
            or type(archive['bytes']) is not int or not 0 < archive['bytes'] <= 100 * 1024 * 1024
            or not isinstance(archive['sha256'], str) or not re.fullmatch('[a-f0-9]{64}', archive['sha256'])):
        raise ComponentError('component_incompatible')
    release = json.loads(json.dumps(base))
    release['version'] = version
    if component == 'amneziawg':
        commit = choice.get('commit')
        if not isinstance(commit, str) or not re.fullmatch('[a-f0-9]{40}', commit) or archive['url'] != (
                'https://codeload.github.com/amnezia-vpn/amneziawg-go/tar.gz/' + commit):
            raise ComponentError('component_incompatible')
        release['commit'] = commit
        release['archives']['source'] = dict(archive)
    elif component == 'trusttunnel':
        if archive['url'] != ('https://github.com/TrustTunnel/TrustTunnel/releases/download/v%s/'
                              'trusttunnel-v%s-linux-x86_64.tar.gz' % (version, version)):
            raise ComponentError('component_incompatible')
        # Per-file hashes are unknown for a release AntiRKN did not pin; the
        # archive hash covers them and the programs are taken by name.
        release['archives']['endpoint'] = dict(archive)
    else:
        raise ComponentError('component_incompatible')
    release['chosen'] = True
    return release


def names(component):
    return ('trusttunnel_endpoint', 'setup_wizard') if component == 'trusttunnel' else ('amneziawg-go', 'awg', 'awg-quick')


def unit_name(component):
    return 'antirkn-trusttunnel.service' if component == 'trusttunnel' else 'antirkn-awg@.service'


def unit_source(component):
    if component == 'trusttunnel':
        body = ('Type=simple\nWorkingDirectory=/etc/antirkn-components/trusttunnel\n'
            'ExecStart=/usr/local/bin/trusttunnel_endpoint vpn.toml hosts.toml\n'
            'Restart=on-failure\nRestartSec=3\n')
    else:
        body = ('Type=oneshot\nRemainAfterExit=yes\n'
            'Environment=PATH=/usr/local/bin:/usr/sbin:/usr/bin:/sbin:/bin\n'
            'Environment=WG_QUICK_USERSPACE_IMPLEMENTATION=/usr/local/bin/amneziawg-go\n'
            'ExecStart=/usr/local/bin/awg-quick up /etc/antirkn-components/amneziawg/%i.conf\n'
            'ExecStop=/usr/local/bin/awg-quick down /etc/antirkn-components/amneziawg/%i.conf\n')
    return ('[Unit]\nDescription=AntiRKN ' + component + '\nAfter=network-online.target\n'
        'Wants=network-online.target\n[Service]\nUMask=0077\n' + body +
        '[Install]\nWantedBy=multi-user.target\n').encode()


def active_units(component):
    patterns = ['antirkn-trusttunnel.service', 'antirkn-tt@*.service'] if component == 'trusttunnel' else ['antirkn-awg@*.service']
    result = run(['/usr/bin/systemctl', 'list-units', '--state=active,activating',
        '--type=service', '--no-legend', '--plain', *patterns], timeout=20)
    if result.returncode:
        raise ComponentError('component_prerequisites')
    units = [line.split()[0] for line in result.stdout.decode().splitlines() if line.strip()]
    if any(not re.fullmatch(r'antirkn-trusttunnel\.service|antirkn-tt@[a-f0-9]{32}\.service|antirkn-awg@[A-Za-z0-9_=+.-]{1,15}\.service', u) for u in units):
        raise ComponentError()
    return sorted(units)


def config_snapshot(component):
    root = CONFIG / component
    if not root.exists() and not root.is_symlink():
        return {}
    safe_directory(CONFIG)
    safe_directory(root)
    result = {}
    for p in root.rglob('*'):
        if len(result) >= 10000:
            raise ComponentError()
        if p.is_symlink():
            raise ComponentError()
        if p.is_dir():
            safe_directory(p)
        else:
            safe_file(p, 1024 * 1024)
        result[str(p.relative_to(root))] = snapshot(p)
    return result


def safe_directory(path):
    st = path.lstat()
    if not stat.S_ISDIR(st.st_mode) or st.st_uid != 0 or st.st_mode & 0o022:
        raise ComponentError()


def snapshot(path):
    if not path.exists() and not path.is_symlink():
        return None
    st = path.lstat()
    if stat.S_ISLNK(st.st_mode):
        return ['link', os.readlink(path)]
    if stat.S_ISREG(st.st_mode):
        if st.st_size > 32 * 1024 * 1024:
            raise ComponentError()
        return ['file', st.st_uid, st.st_mode, digest(path)]
    return ['directory', st.st_uid, st.st_mode, st.st_ino]


def installed(component):
    root = BASE / component
    if not root.exists() and not root.is_symlink():
        return None
    safe_directory(BASE)
    safe_directory(root)
    pointer = root / 'current'
    if not pointer.is_symlink():
        # An interrupted first install has no committed public version yet.
        return None
    target = os.readlink(pointer)
    if not re.fullmatch(r'versions/[a-f0-9]{64}', target):
        raise ComponentError()
    version = root / target
    safe_directory(root / 'versions')
    safe_directory(version)
    safe_file(version / 'manifest.json')
    record = json.loads((version / 'manifest.json').read_text())
    if record['component'] != component or record['release'] != target.split('/')[1]:
        raise ComponentError()
    for name, expected in record['files'].items():
        if not re.fullmatch(r'[A-Za-z0-9_.-]+', name):
            raise ComponentError()
        safe_file(version / name, 100 * 1024 * 1024)
        if digest(version / name) != expected:
            raise ComponentError()
    if not set(names(component)) <= set(record['files']):
        raise ComponentError()
    return record


def external_paths(component):
    if component == 'trusttunnel':
        return [Path(p) for p in ('/opt/trusttunnel', '/etc/trusttunnel',
            '/etc/systemd/system/trusttunnel.service', '/lib/systemd/system/trusttunnel.service',
            '/usr/bin/trusttunnel_endpoint')]
    return [Path(p) for p in ('/usr/bin/awg', '/usr/bin/amneziawg-go', '/usr/bin/awg-quick',
        '/opt/amnezia', '/etc/amnezia', '/etc/amneziawg', '/sys/module/amneziawg',
        '/etc/systemd/system/awg-quick@.service', '/lib/systemd/system/awg-quick@.service')]


def component_plan(component, payload=None):
    if component not in RELEASES:
        raise ComponentError('component_incompatible')
    release = release_for(component, payload)
    record, conflict = None, False
    try:
        record = installed(component)
    except (ValueError, KeyError, TypeError, OSError, ComponentError, PanelError):
        conflict = True
    paths = external_paths(component) + [BIN / name for name in names(component)]
    unit = UNITS / unit_name(component)
    if unit.exists() or unit.is_symlink():
        try:
            safe_file(unit)
            conflict |= unit.read_bytes() != unit_source(component) or record is None
        except (OSError, ValueError, PanelError):
            conflict = True
    observed = {str(p): snapshot(p) for p in paths}
    for path in paths:
        value = observed[str(path)]
        own_link = path in [BIN / name for name in names(component)] and value == ['link', str(BASE / component / 'current' / path.name)]
        if value is not None and not own_link:
            conflict = True
    containers = []
    if shutil.which('docker'):
        result = sysutil_run(['docker', 'ps', '-a', '--format', '{{.Image}} {{.Names}}'], timeout=20)
        if result.returncode:
            conflict = True
        else:
            containers = sorted(line for line in result.stdout.decode().splitlines()
                if any(n in line.lower() for n in ('trusttunnel',) if component == 'trusttunnel')
                or component == 'amneziawg' and any(n in line.lower() for n in ('amnezia', 'amneziawg', 'awg')))
            conflict |= bool(containers)
    missing = []
    distro = dict(line.split('=', 1) for line in Path('/etc/os-release').read_text().splitlines() if '=' in line)
    if distro.get('ID', '').strip('"') != 'ubuntu' or platform.machine() != 'x86_64':
        missing.append('ubuntu_x64')
    if not Path('/etc/ssl/certs/ca-certificates.crt').exists():
        missing.append('ca_certificates')
    if component == 'amneziawg' and not Path('/dev/net/tun').exists():
        missing.append('tun')
    required = (2000 if component == 'amneziawg' else 150) * 1024 * 1024
    if min(shutil.disk_usage('/usr/local').free, shutil.disk_usage('/var/lib').free) < required:
        missing.append('disk_space')
    state = 'conflict' if conflict else 'missing' if record is None else 'current' if record['release'] == release_hash(component, release) else 'update'
    # Never downgrade or cross an unknown generation with a generic updater.
    if state == 'update' and (record['version'].split('.')[0] != release['version'].split('.')[0]
            or tuple(map(int, record['version'].split('.'))) > tuple(map(int, release['version'].split('.')))):
        state = 'incompatible'
    if state == 'update' and component == 'amneziawg' and (
            not re.fullmatch(r'[0-9]+\.[0-9]+\.[0-9]+', record.get('toolsVersion') or '')
            or record['toolsVersion'].split('.')[0] != release['toolsVersion'].split('.')[0]
            or tuple(map(int, record['toolsVersion'].split('.'))) > tuple(map(int, release['toolsVersion'].split('.')))):
        state = 'incompatible'
    data = dict(component=component, state=state, supported=not missing,
        prerequisites=missing, version=release['version'], toolsVersion=release.get('toolsVersion'),
        installedVersion=record['version'] if record else None, release=release_hash(component, release),
        chosen=bool(release.get('chosen')),
        archives=release['archives'], previous=record, paths=observed, containers=containers,
        activeUnits=active_units(component), unit=snapshot(unit), config=config_snapshot(component))
    data['fingerprint'] = hashlib.sha256(encode(data)).hexdigest()
    return data


def extract(archive, destination, kind, maximum=600 * 1024 * 1024):
    """No links/devices/traversal/duplicate entries, including on Python 3.8."""
    destination.mkdir(mode=0o700, exist_ok=True)
    seen, total = set(), 0
    source = zipfile.ZipFile(archive) if kind == 'zip' else tarfile.open(archive, 'r:gz')
    try:
        entries = source.infolist() if kind == 'zip' else source.getmembers()
        if len(entries) > 30000:
            raise ComponentError('component_checksum_failed')
        for item in entries:
            name = item.filename if kind == 'zip' else item.name
            path = PurePosixPath(name)
            size = item.file_size if kind == 'zip' else item.size
            directory = item.is_dir() if kind == 'zip' else item.isdir()
            regular = not stat.S_ISLNK(item.external_attr >> 16) if kind == 'zip' else item.isfile() or directory
            total += size
            if path.is_absolute() or '..' in path.parts or '\\' in name or name in seen or not regular or total > maximum:
                raise ComponentError('component_checksum_failed')
            seen.add(name)
            target = destination.joinpath(*path.parts)
            target.parent.mkdir(parents=True, mode=0o700, exist_ok=True)
            if directory:
                target.mkdir(mode=0o700, exist_ok=True)
            else:
                if target.is_symlink():
                    raise ComponentError()
                with (source.open(item) if kind == 'zip' else source.extractfile(item)) as src, target.open('wb') as dst:
                    shutil.copyfileobj(src, dst)
                target.chmod(0o755 if kind != 'zip' and item.mode & 0o111 else 0o600)
    finally:
        source.close()


class ComponentInstaller:
    def __init__(self, store, request):
        self.store, self.request = store, request
        self.component = request['component']
        self.payload = request.get('payload') or None
        self.release = release_for(self.component, self.payload)
        self.directory = store.directory / ('component-' + request['id'])
        self.root = BASE / self.component

    def checkpoint(self, number, code):
        with self.store.db:
            self.store.db.execute('UPDATE jobs SET checkpoint=? WHERE id=?', (number, self.request['id']))
            self.store.event(self.request['id'], code, number, STEPS)

    def cancelled(self):
        return bool(self.store.db.execute('SELECT cancel FROM jobs WHERE id=?', (self.request['id'],)).fetchone()[0])

    def download(self, name, artifact):
        try:
            return fetch_pinned(artifact['url'], self.directory / (name + '.archive'),
                                artifact['bytes'], artifact['sha256'], self.cancelled)
        except DownloadError as error:
            raise ComponentError({'cancelled': 'cancelled', 'checksum': 'component_checksum_failed'}.get(
                error.reason, 'component_download_failed')) from None

    def verify(self, directory):
        for name, expected in (('trusttunnel_endpoint', self.release['version']),) if self.component == 'trusttunnel' else (
                ('amneziawg-go', self.release['version']), ('awg', self.release['toolsVersion'])):
            result = run([str(directory / name), '--version'], timeout=20)
            if result.returncode or expected not in result.stdout.decode(errors='replace'):
                raise ComponentError('component_check_failed')

    def build(self):
        output = self.directory / 'output'
        prepared = self.directory / '.build_prepared'
        if not prepared.exists():
            output.mkdir(mode=0o700, exist_ok=True)
            for name, artifact in self.release['archives'].items():
                extract(self.directory / (name + '.archive'), self.directory / name, 'zip' if name == 'tools' else 'tar')
                for filename, expected in artifact.get('files', {}).items():
                    matches = list((self.directory / name).glob('*/' + filename))
                    if len(matches) != 1 or digest(matches[0]) != expected:
                        raise ComponentError('component_checksum_failed')
                    shutil.copyfile(matches[0], output / filename)
                if self.release.get('chosen') and self.component == 'trusttunnel' and name == 'endpoint':
                    for filename in names(self.component):
                        matches = [m for m in (self.directory / name).rglob(filename) if m.is_file() and not m.is_symlink()]
                        if len(matches) != 1:
                            raise ComponentError('component_checksum_failed')
                        shutil.copyfile(matches[0], output / filename)
            if self.component == 'amneziawg':
                source = self.directory / 'source' / ('amneziawg-go-' + self.release['commit'])
                (source / 'version.go').write_text('package main\nconst Version = "v' + self.release['version'] + '"\n')
            atomic_file(prepared, b'ok')

        if self.component == 'amneziawg':
            source = self.directory / 'source' / ('amneziawg-go-' + self.release['commit'])
            target_bin = output / 'amneziawg-go'
            state_file = self.directory / 'build_pid.json'
            job_id = self.request['id']

            if job_id not in BUILD_PROCESSES:
                if state_file.exists():
                    try:
                        info = json.loads(state_file.read_text())
                    except (OSError, ValueError):
                        info = {}
                    pid = info.get('pid') if isinstance(info, dict) else None
                    if same_process(pid, info.get('identity') if isinstance(info, dict) else None):
                        if self.cancelled() or time.time() > info.get('deadline', 0):
                            try:
                                os.killpg(pid, signal.SIGTERM)
                            except OSError:
                                pass
                            state_file.unlink(missing_ok=True)
                            raise ComponentError('cancelled' if self.cancelled() else 'component_build_failed')
                        return False
                    # The build ended while no worker watched it (restart or
                    # reboot), or the PID now names another process. Its exit
                    # status is unknown: discard its output, build again.
                    state_file.unlink(missing_ok=True)
                    target_bin.unlink(missing_ok=True)
                if not target_bin.is_file():
                    env = dict(PATH='/usr/bin:/bin', HOME=str(self.directory), CGO_ENABLED='0', GOOS='linux', GOARCH='amd64',
                        GOTOOLCHAIN='local', GOPROXY='https://proxy.golang.org', GOSUMDB='sum.golang.org',
                        GOCACHE=str(self.directory / 'go-cache'), GOPATH=str(self.directory / 'go-path'), GOMAXPROCS='2')
                    # No make/generate hooks; -mod=readonly preserves the upstream sums.
                    process = subprocess.Popen([str(self.directory / 'go/go/bin/go'), 'build', '-mod=readonly', '-trimpath',
                        '-buildvcs=false', '-o', str(target_bin), '.'], cwd=source, env=env,
                        stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL, start_new_session=True)
                    deadline = time.time() + 1200
                    BUILD_PROCESSES[job_id] = (process, deadline)
                    atomic_file(state_file, json.dumps(dict(pid=process.pid, deadline=deadline,
                        identity=process_identity(process.pid))).encode())
                    return False
            else:
                process, deadline = BUILD_PROCESSES[job_id]
                if self.cancelled() or time.time() > deadline:
                    try:
                        os.killpg(process.pid, signal.SIGTERM)
                        try:
                            process.wait(timeout=2)
                        except subprocess.TimeoutExpired:
                            os.killpg(process.pid, signal.SIGKILL)
                            process.wait(timeout=10)
                    except (OSError, subprocess.SubprocessError):
                        pass
                    BUILD_PROCESSES.pop(job_id, None)
                    state_file.unlink(missing_ok=True)
                    raise ComponentError('cancelled' if self.cancelled() else 'component_build_failed')

                ret = process.poll()
                if ret is None:
                    return False

                BUILD_PROCESSES.pop(job_id, None)
                state_file.unlink(missing_ok=True)
                if ret != 0:
                    raise ComponentError('component_build_failed')

        for name in names(self.component):
            (output / name).chmod(0o755)
        self.verify(output)
        for path in output.iterdir():
            with path.open('rb') as stream:
                os.fsync(stream.fileno())
        sync_directory(output)
        return True

    def step(self, number):
        if number == 0:
            plan = component_plan(self.component, self.payload)
            if plan['fingerprint'] != self.request['fingerprint'] or plan['state'] not in ('missing', 'update'):
                raise ComponentError()
            if not plan['supported']:
                raise ComponentError('component_prerequisites')
            self.directory.mkdir(mode=0o700, exist_ok=True)
            atomic_file(self.directory / 'plan.json', encode(plan))
            self.checkpoint(1, 'component_prepared')
            return True
        safe_directory(self.directory)
        safe_file(self.directory / 'plan.json')
        plan = json.loads((self.directory / 'plan.json').read_text())
        if plan['fingerprint'] != self.request['fingerprint']:
            raise ComponentError()
        if number == 1:
            for name, artifact in self.release['archives'].items():
                self.download(name, artifact)
            self.checkpoint(2, 'component_downloaded')
            return True
        elif number == 2:
            if not self.build():
                return False
            self.checkpoint(3, 'component_built')
            return True
        elif number == 3:
            # Revalidate before the first public effect. An interrupted staging
            # directory is private; the published pointer is still unchanged.
            if component_plan(self.component, self.payload)['fingerprint'] != plan['fingerprint']:
                raise ComponentError()
            backup = self.directory / 'config-backup'
            backup.mkdir(mode=0o700, exist_ok=True)
            for name, entry in plan['config'].items():
                if entry[0] == 'file':
                    dest = backup / name
                    dest.parent.mkdir(mode=0o700, parents=True, exist_ok=True)
                    atomic_copy(CONFIG / self.component / name, dest)
            for directory in (BASE, self.root, self.root / 'versions'):
                directory.mkdir(mode=0o755, exist_ok=True)
                safe_directory(directory)
            target = self.root / 'versions' / release_hash(self.component, self.release)
            staging = self.root / 'versions' / ('.' + self.request['id'])
            staging.mkdir(mode=0o755, exist_ok=True)
            hashes = {}
            for file in (self.directory / 'output').iterdir():
                safe_file(file, 100 * 1024 * 1024)
                atomic_copy(file, staging / file.name, 0o755 if file.name in names(self.component) else 0o644)
                hashes[file.name] = digest(file)
            record = dict(component=self.component, version=self.release['version'],
                toolsVersion=self.release.get('toolsVersion'), release=release_hash(self.component, self.release), files=hashes)
            atomic_file(staging / 'manifest.json', encode(record), 0o644)
            if not (self.directory / 'probe-before.json').exists():
                atomic_file(self.directory / 'probe-before.json', encode(self.probe()))
            atomic_file(self.directory / 'target.json', encode(record))
            if not target.exists():
                os.rename(staging, target)
                sync_directory(target.parent)
            elif staging.exists():
                # The same immutable release is already published.
                shutil.rmtree(str(staging))
            if (target / 'manifest.json').read_bytes() != encode(record):
                raise ComponentError()
            self.checkpoint(4, 'component_staged')
            return True
        elif number == 4:
            safe_file(self.directory / 'target.json')
            target = json.loads((self.directory / 'target.json').read_text())
            current = installed(self.component)
            if current not in (plan['previous'], target):
                raise ComponentError()
            if active_units(self.component) != plan['activeUnits']:
                raise ComponentError()
            if config_snapshot(self.component) != plan['config']:
                raise ComponentError()
            # Check all public paths before the pointer change, and tolerate
            # only this operation's exact links when resuming after a crash.
            for path, before in plan['paths'].items():
                now = snapshot(Path(path))
                own = ['link', str(self.root / 'current' / Path(path).name)]
                if now != before and not (Path(path).parent == BIN and now == own):
                    raise ComponentError()
            unit = UNITS / unit_name(self.component)
            if snapshot(unit) != plan['unit']:
                safe_file(unit)
                if unit.read_bytes() != unit_source(self.component):
                    raise ComponentError()
            # Configurations and keys are untouched. The previous complete
            # immutable directory plus this journal is the software backup.
            pointer = self.root / 'current'
            temp = self.root / '.current-next'
            if temp.is_symlink():
                temp.unlink()
            os.symlink('versions/' + release_hash(self.component, self.release), temp)
            os.replace(temp, pointer)
            sync_directory(self.root)
            for name in names(self.component):
                link = BIN / name
                expected = str(self.root / 'current' / name)
                if link.exists() or link.is_symlink():
                    if not link.is_symlink() or os.readlink(link) != expected:
                        raise ComponentError()
                else:
                    os.symlink(expected, link)
            sync_directory(BIN)
            CONFIG.mkdir(mode=0o700, exist_ok=True)
            safe_directory(CONFIG)
            (CONFIG / self.component).mkdir(mode=0o700, exist_ok=True)
            atomic_file(unit, unit_source(self.component), 0o644)
            sysutil_run(['/usr/bin/systemctl', 'daemon-reload'], check=True, timeout=30, capture=False, stderr=False)
            self.checkpoint(5, 'component_switched')
            return True
        elif number == 5:
            record = installed(self.component)
            if record != json.loads((self.directory / 'target.json').read_text()):
                raise ComponentError()
            try:
                self.verify(self.root / 'current')
                for unit in plan['activeUnits']:
                    sysutil_run(['/usr/bin/systemctl', 'restart', unit], check=True, timeout=90, capture=False, stderr=False)
                    sysutil_run(['/usr/bin/systemctl', 'is-active', '--quiet', unit], check=True, timeout=20)
                self.connections_kept()
            except (ComponentError, OSError, subprocess.SubprocessError) as error:
                cause = error.code if isinstance(error, ComponentError) and error.code == 'upgrade_connectivity_failed' else 'component_check_failed'
                with self.store.db:
                    self.store.event(self.request['id'], cause, 5, STEPS)
                if plan['previous'] and self.restore_previous(plan):
                    raise ComponentError('upgrade_rolled_back')
                raise
            self.checkpoint(6, 'component_checked')
            return True

    def probe(self):
        """Real connectivity of what this component serves ({} when unknown)."""
        try:
            from component_upgrade import probe_component
            return probe_component(self.component)
        except Exception:
            return {}

    def connections_kept(self):
        """Endpoints/interfaces that worked before the switch work after it."""
        try:
            before = json.loads((self.directory / 'probe-before.json').read_text())
        except (OSError, ValueError):
            return
        if not any(before.values()):
            return
        deadline = time.monotonic() + 30
        while True:
            after = self.probe()
            if not [k for k, ok in before.items() if ok and not after.get(k)]:
                return
            if time.monotonic() > deadline:
                raise ComponentError('upgrade_connectivity_failed')
            time.sleep(3)

    def restore_previous(self, plan):
        """Point back to the previous immutable version and restart its units."""
        previous = self.root / 'versions' / plan['previous']['release']
        if not (previous / 'manifest.json').is_file():
            return False
        temp = self.root / '.current-next'
        if temp.is_symlink():
            temp.unlink()
        os.symlink('versions/' + plan['previous']['release'], temp)
        os.replace(temp, self.root / 'current')
        sync_directory(self.root)
        for unit in plan['activeUnits']:
            sysutil_run(['/usr/bin/systemctl', 'restart', unit], timeout=90, capture=False, stderr=False)
        # Nothing of this operation remains public: the job ends as failed.
        (self.directory / 'target.json').unlink(missing_ok=True)
        return True

    def abort(self):
        job_id = self.request['id']
        proc_entry = BUILD_PROCESSES.pop(job_id, None)
        if proc_entry:
            process = proc_entry[0] if isinstance(proc_entry, tuple) else proc_entry
            try:
                os.killpg(process.pid, signal.SIGTERM)
                try:
                    process.wait(timeout=2)
                except subprocess.TimeoutExpired:
                    os.killpg(process.pid, signal.SIGKILL)
                    process.wait(timeout=10)
            except (OSError, subprocess.SubprocessError):
                pass
        state_file = self.directory / 'build_pid.json'
        if state_file.exists():
            try:
                info = json.loads(state_file.read_text())
                if isinstance(info, dict) and same_process(info.get('pid'), info.get('identity')):
                    os.killpg(info['pid'], signal.SIGTERM)
            except (OSError, ValueError):
                pass
            state_file.unlink(missing_ok=True)
        # A private, unpublished staging copy never outlives its job.
        staging = self.root / 'versions' / ('.' + job_id)
        if staging.is_dir() and not staging.is_symlink():
            shutil.rmtree(str(staging), ignore_errors=True)
        # Staging/pointer change may have completed without its checkpoint.
        return 'partially_applied' if (self.directory / 'target.json').exists() else 'cancelled'

